using System;using System.Linq;using System.IO;using System.Reflection;using System.Windows.Forms;using System.Drawing;using System.Collections.Generic;using System.Threading;
class SpellPracticeChecks {
 static BindingFlags F=BindingFlags.NonPublic|BindingFlags.Instance;
 static object Call(Game g,string n,params object[] args){return typeof(Game).GetMethod(n,F).Invoke(g,args);}static T Get<T>(Game g,string n){return (T)typeof(Game).GetField(n,F).GetValue(g);}static void Set(Game g,string n,object v){typeof(Game).GetField(n,F).SetValue(g,v);}static void Check(bool b,string m){if(!b)throw new Exception(m);}
 static void Snapshot(Control c,string name){using(var bitmap=new Bitmap(c.Width,c.Height)){c.DrawToBitmap(bitmap,c.ClientRectangle);bitmap.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,name+".png"));}}
 static void Modal(Game g,string method,object[] args,string name){var timer=new System.Windows.Forms.Timer{Interval=500};timer.Tick+=(s,e)=>{foreach(Form f in Application.OpenForms.Cast<Form>().ToArray())if(f!=g){Snapshot(f,name);f.Close();timer.Stop();}};timer.Start();Call(g,method,args);timer.Dispose();}
 static IEnumerable<Control> All(Control c){foreach(Control child in c.Controls){yield return child;foreach(var nested in All(child))yield return nested;}}
 static void QuizReward(Game game,Save save,RealListeningExam exam){foreach(string id in WaystationChapterOne.Ids)if(!save.completed.Contains(id))save.completed.Add(id);save.tavernBusiness=new TavernBusinessState();TavernBusiness.Begin(save,"listening");int before=save.rogue.coins;Exception error=null;var timer=new System.Windows.Forms.Timer{Interval=400};timer.Tick+=(s,e)=>{try{var dialog=Application.OpenForms.Cast<Form>().FirstOrDefault(f=>f!=game);if(dialog==null)return;timer.Stop();var buttons=All(dialog).OfType<VNButton>().ToList();Check(!All(dialog).OfType<OutlinedLabel>().Any(l=>l.Text.Contains("正确答案")),"answer revealed before submit");buttons.First(b=>b.Text.StartsWith(((char)('A'+exam.questions[0].answer))+".")).PerformClick();buttons.First(b=>b.Text=="提交答案").PerformClick();Check(save.rogue.coins==before+5,"first correct answer reward missing");buttons.First(b=>b.Text=="重新作答本题").PerformClick();buttons.First(b=>b.Text.StartsWith(((char)('A'+exam.questions[0].answer))+".")).PerformClick();buttons.First(b=>b.Text=="提交答案").PerformClick();Check(save.rogue.coins==before+5,"repeated question awarded twice");dialog.Close();}catch(Exception ex){error=ex;timer.Stop();foreach(Form f in Application.OpenForms.Cast<Form>().ToArray())if(f!=game)f.Close();}};timer.Start();Call(game,"ShowSpellQuestions",new object[]{null});timer.Dispose();if(error!=null)throw error;}
 static void SentenceTail(Game game){
 var chapter=Get<Chapter>(game,"current");var savedLines=chapter.lines;int savedIndex=Get<int>(game,"index");double start=savedLines[savedIndex].start;
 try{var lines=new List<Line>{new Line{start=start,end=start+.2,text="Tail playback check",translation="句尾播放检查"},new Line{start=start+2,end=start+3,text="Next sentence"}};
 Check(SpellPracticeAudio.SentenceEndMs(lines,0)==(long)Math.Round((start+.7)*1000),"sentence tail padding missing");
 lines[1].start=start+.5;Check(SpellPracticeAudio.SentenceEndMs(lines,0)==(long)Math.Round((start+.5)*1000),"padding entered next sentence");lines[1].start=start+2;
 chapter.lines=lines;Set(game,"index",0);Call(game,"StartLine",false);Thread.Sleep(240);Application.DoEvents();Call(game,"AudioTick",null,EventArgs.Empty);Check(Get<bool>(game,"originalPlaying"),"playback completed at unpadded caption end");Thread.Sleep(650);Application.DoEvents();Call(game,"AudioTick",null,EventArgs.Empty);Check(!Get<bool>(game,"originalPlaying"),"sentence playback did not finish at padded end");
 }finally{Call(game,"StopAudio");chapter.lines=savedLines;Set(game,"index",savedIndex);Call(game,"UpdateLine");}
 }
 [STAThread]static void Main(){Application.SetUnhandledExceptionMode(UnhandledExceptionMode.ThrowException);Application.EnableVisualStyles();using(var game=new Game()){game.Show();game.Opacity=0;game.Size=new Size(1280,780);Application.DoEvents();var save=new Save();save.fullscreen=false;Set(game,"save",save);var original=Get<Chapter>(game,"current");int originalIndex=Get<int>(game,"index");Call(game,"ShowTavernListeningList",4);Application.DoEvents();Snapshot(game,"spell-library");var bank=(List<RealListeningExam>)Call(game,"RealListeningBank",4);var exam=bank.First(e=>e.lines!=null&&e.lines.Count>0);Call(game,"OpenSpellPractice",exam);Application.DoEvents();Check((bool)Call(game,"IsSpellPractice"),"practice not open");Check(save.positions.Count==0&&!save.hasGame,"main progress changed");Check((bool)Call(game,"SetStorySubtitle",true,true),"Chinese toggle");Check(Get<OutlinedLabel>(game,"translationLabel").Text.Length>0,"Chinese subtitle empty");Call(game,"Next");Call(game,"Previous");Check(save.sectionAttempts.Count==0,"practice created main rating");Call(game,"StartLine",false);System.Threading.Thread.Sleep(350);Application.DoEvents();Check(Get<bool>(game,"audioReady")&&Get<bool>(game,"originalPlaying"),"real audio did not open/play");Call(game,"StopAudio");SentenceTail(game);var firstQuestion=exam.questions[0];Set(game,"spellReplayEndMs",(long)(firstQuestion.end*1000));Set(game,"allPlaying",true);Call(game,"StartLine",true);Check(Get<long>(game,"storyEndMs")== (long)(firstQuestion.end*1000),"group playback escaped boundary");Call(game,"StopAudio");Snapshot(game,"spell-dialogue");Call(game,"AddWord","table","a table");Application.DoEvents();foreach(Form f in Application.OpenForms.Cast<Form>().ToArray())if(f!=game){Snapshot(f,"spell-word");Check(!f.Controls.OfType<ScrollableControl>().Any(c=>c.AutoScroll),"word has native scrollbar");f.Close();}Modal(game,"ShowSpellQuestions",new object[]{null},"spell-question");Modal(game,"ShowSpellTranscript",new object[0],"spell-transcript");Modal(game,"ShowSpellGroups",new object[0],"spell-groups");QuizReward(game,save,exam);game.Size=new Size(800,500);Application.DoEvents();Snapshot(game,"spell-dialogue-small");Modal(game,"ShowSpellQuestions",new object[]{null},"spell-question-small");Call(game,"ReturnSpellPracticeLibrary");Check(Get<Chapter>(game,"current")==original&&Get<int>(game,"index")==originalIndex,"original chapter not restored");var bank4=(List<RogueEntry>)Call(game,"TrainingPool","四级训练");var bank6=(List<RogueEntry>)Call(game,"TrainingPool","六级训练");foreach(var mode in KitchenVocabulary.Modes){var state=(KitchenWorkState)Call(game,"KitchenState");state.wordMode=mode;state.cutWords=null;Call(game,"PrepareKitchenWords","cut");Check(state.cutWords.Count==3,"batch incomplete");var expected=mode==KitchenVocabulary.Modes[0]?bank4:mode==KitchenVocabulary.Modes[1]?bank6:bank4.Concat(bank6).ToList();Check(state.cutWords.All(w=>expected.Any(e=>e.word==w.word)),"wrong kitchen vocabulary");state.boardLoaded=true;state.cut=0;Check(!state.Answer("cut","incorrect"),"wrong answer accepted");Check(state.Answer("cut",state.cutWords[0].word),"correct answer rejected");}
 game.Close();}Console.WriteLine("PASS: real exam dialogue, subtitles, navigation, isolated progress, modal close, small layout, CET kitchen vocabulary and spelling.");}
}
